const sourceRecordsOfCustomer = `-- name: SourceRecordsOfCustomer :many
SELECT p.id FROM profiles p
WHERE p.creator_source = $1::text AND (p.id = $2::uuid
  OR p.id IN (SELECT profile_id FROM profile_aliases WHERE canonical_id = $2::uuid))
ORDER BY p.id LIMIT 2
`

type SourceRecordsOfCustomerParams struct {
	Source      string
	CanonicalID string
}

// A source's own profiles in the unified customer that profile_id belongs to.
func (q *Queries) SourceRecordsOfCustomer(ctx context.Context, arg SourceRecordsOfCustomerParams) ([]string, error) {
	rows, err := q.db.Query(ctx, sourceRecordsOfCustomer, arg.Source, arg.CanonicalID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

